function cid(){return 'c'+Math.random().toString(36).slice(2,9);}
function genWxid(){return 'wx_'+Math.random().toString(36).slice(2,9);}
function curMonth(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,6);}

function pruneDailyMood(){if(!Array.isArray(S.mood))return false;const now=Date.now(),cut=now-86400000;const before=S.mood.length;
  S.mood=S.mood.filter(m=>{const ts=+(m.time||m.ts||0);if(ts)return ts>=cut;const d=(''+(m.date||'')).slice(0,10);return d&&d===todayStr();});
  return S.mood.length!==before;}
function tvStampKey(city){return (city||'').trim().toLowerCase();}
function tvDedupeStamps(t){if(!t||!Array.isArray(t.stamps))return false;const seen={};const before=t.stamps.length;
  t.stamps=t.stamps.filter(s=>{const k=tvStampKey(s&&s.city);if(!k||seen[k])return false;seen[k]=1;return true;});
  return t.stamps.length!==before;}
function tvAddStamp(t,city,cid,date){if(!t)return false;t.stamps=t.stamps||[];const k=tvStampKey(city);if(!k)return false;
  if(t.stamps.some(s=>tvStampKey(s.city)===k))return false;
  t.stamps.push({city,code:tvCity(city).c,cid:cid||'',date,ts:Date.now()});return true;}
function roleReplyEnglishOnly(value){
  const pick=(node,depth)=>{if(depth>6||node==null)return '';if(typeof node==='string')return node;if(Array.isArray(node))return node.map(x=>pick(x,depth+1)).join('\n');if(typeof node!=='object')return '';return ['content','text','reply','message','answer','output','response','body','bubbles','messages','translation','trans'].filter(k=>node[k]!=null).map(k=>pick(node[k],depth+1)).join('\n');};
  let text=typeof value==='string'?value:pick(value,0);
  const json=String(text||'').trim().replace(/^\x60\x60\x60(?:json)?\s*/i,'').replace(/\s*\x60\x60\x60$/,'');
  if(/^(?:\x7b|\[)/.test(json)){try{text=pick(JSON.parse(json),0);}catch(_){}}
  text=String(text||'');
  text=text.replace(/[\[【]\s*(?:内心|心情|心情值|小事簿|记住|记忆|闹钟|日程|来电|挂断|联网|发推|发朋友圈|发抖音|锁定|解锁|禁言|解禁|限时|加时|记仇|消气|控制|改备注|换头像|共同生活状态|同居状态|共同生活位置|同居位置)\s*(?:[|｜:：][^\]】]*)?[\]】]/g,'');
  text=text.replace(/[\[【]\s*([\u3400-\u9fff]{1,20})\s*[|｜:：]\s*([^\]】]*)[\]】]/g,(tag,name,body)=>/^(?:语音|翻译|中文翻译)$/.test(name)?body.replace(/[|｜]\s*语气\s*[:：][^|｜]*$/,''):'').replace(/(?:^|\n)\s*(?:翻译|中文翻译|中文|原文|英文)\s*[:：]\s*/g,'\n');
  const outside=text.replace(/<(?:think|analysis|reasoning)>[\s\S]*?<\/(?:think|analysis|reasoning)>/gi,'');
  text=outside.trim()?outside:text.replace(/<\/?(?:think|analysis|reasoning)>/gi,'');
  return /[A-Za-z]/.test(text)&&!/[\u3400-\u9fff\uf900-\ufaff\u3040-\u30ff\uac00-\ud7af\u0370-\u052f\u0590-\u08ff\u0900-\u0fff]/.test(text);
}
/* 混合回复里的整段英文旁白：本地丢弃即可，不重新生成。只认【】且整段没有一个中文字的，
   台词里夹的英文单词、歌名、地名一律不动；万一全删空就原样退回，交给下面的纯英文拦截。 */
function roleReplyDropEnglishNarration(value){const raw=typeof value==='string'?value:'';if(!raw||raw.indexOf('【')<0)return value;let dropped=false;const out=raw.replace(/【([^【】]*)】/g,(whole,inner)=>{if(!/[A-Za-z]/.test(inner))return whole;if(/[㐀-䶿一-鿿豈-﫿]/.test(inner))return whole;dropped=true;return '';});if(!dropped)return value;const cleaned=out.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();return cleaned||value;}
function roleReplyAssertLanguage(value,audit){
  if(!roleReplyEnglishOnly(value))return value;
  const reason='已拦截纯英文回复：没有中文翻译';
  if(audit&&audit.c&&typeof roleInterceptDiagnosticRemember==='function')roleInterceptDiagnosticRemember(audit.c,audit.channel,value,reason,'英文拦截始终生效，不能作为角色消息释放',audit.account);
  const error=new Error(reason);error.code='ROLE_ENGLISH_ONLY';error.roleOutputRaw=String(value||'');throw error;
}
