function currentClockSpoken(t){const d=roleTimeParts(t||Date.now()),h=d.hour,m=d.minute,part=h<5?'凌晨':h<9?'早上':h<12?'上午':h<14?'中午':h<18?'下午':h<23?'晚上':'深夜',hour=h%12||12;return part+clockCNNumber(hour)+'点'+(m===0?'整':m===30?'半':clockCNNumber(m)+'分');}
