function refreshDirectClockReply(content,userText,now){content=String(content||'');if(!S.settings.timeAware||!directClockQuestion(userText))return content;const exact=currentClockSpoken(now||Date.now()),re=/(?:凌晨|早上|上午|中午|下午|傍晚|晚上|夜里|深夜)?\s*(?:(?:[01]?\d|2[0-3]):[0-5]\d|[零〇一二三四五六七八九十两\d]{1,3}\s*(?:点|时)(?:\s*(?:[零〇一二三四五六七八九十两\d]{1,3}\s*分?|半|一刻|三刻|整))?)/;return re.test(content)?content.replace(re,exact):content;}
