function clockNumberValue(token){token=String(token||'').trim();if(/^\d+$/.test(token))return+token;const map={零:0,'〇':0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};if(token==='十')return 10;const at=token.indexOf('十');if(at>=0){const a=at===0?1:(map[token[at-1]]==null?0:map[token[at-1]]),b=at===token.length-1?0:(map[token[at+1]]==null?0:map[token[at+1]]);return a*10+b;}return token.length===1&&map[token]!=null?map[token]:NaN;}
